// Selection translation: common classroom vocabulary works offline.
const classroomGlossary={uncertainty:'不确定性',uncertain:'不确定的',outcome:'结果',outcomes:'结果',random:'随机的','random variable':'随机变量',variable:'变量',probability:'概率',probabilities:'概率',distribution:'分布','probability distribution':'概率分布','probability distributions':'概率分布',entropy:'熵','shannon entropy':'香农熵',clustering:'聚类',clusters:'簇／聚类分组',similar:'相似的',similarity:'相似性',distance:'距离',distances:'距离',observations:'观测数据',observation:'观测',predefined:'预先定义的',labels:'标签','class labels':'类别标签',coordinate:'坐标','coordinate systems':'坐标系',geographical:'地理的',scale:'尺度',uniform:'均匀的','uniform distribution':'均匀分布',concentrated:'集中的',predictable:'可预测的','non-negative':'非负的','add up to one':'总和为 1',fair:'公平的',biased:'有偏的','fair coin':'公平硬币','biased coin':'有偏硬币',coin:'硬币',bits:'比特',bit:'比特','unsupervised learning':'无监督学习',unsupervised:'无监督的',technique:'方法／技术',measure:'衡量／度量',mass:'概率质量',finite:'有限的',within:'在……内部',between:'在……之间',heads:'硬币正面','log base two':'以 2 为底的对数',sum:'总和',information:'信息',calculate:'计算',sketch:'画草图',explain:'解释'};
let selectedPhrase=null;
function showSelectionTranslation(event){if(event?.target?.closest?.("#popover"))return;const selection=window.getSelection();if(!selection||selection.isCollapsed)return;const node=selection.anchorNode?.parentElement;if(!node||node.closest('input,textarea,canvas,#popover'))return;const segment=node.closest('.segment'),uploaded=node.closest('.uploaded-text');if(!segment&&!uploaded)return;const raw=selection.toString().trim();if(!raw||!/[a-z]/i.test(raw)||raw.length>450)return;const rect=selection.getRangeAt(0).getBoundingClientRect();const key=raw.toLowerCase().replace(/^[\s.,:;!?"'()]+|[\s.,:;!?"'()]+$/g,'');let translation=classroomGlossary[key];if(!translation&&segment){const record=getSegment(segment.id);if(raw===record.en)translation=record.zh;}
 selectedPhrase={text:raw,segment:segment?.id||null};const pop=$('#popover');pop.innerHTML=`<div class="pop-head"><span class="term-en">EN → 中文 · 划词翻译</span><button class="icon-btn" data-action="closePopover" aria-label="关闭翻译">×</button></div><p style="font-size:13px;color:#3d5140;margin-bottom:8px">${esc(raw)}</p><div id="selectionResult">${translation?`<h3>${esc(translation)}</h3><small>课堂离线词库${segment?' · 结合本段语境理解':''}</small>`:'<p>点击下方按钮翻译所选英文。</p>'}</div>${segment&&!translation?`<details><summary class="source-link">查看本段参考译文</summary><p>${esc(getSegment(segment.id).zh)}</p></details>`:''}<div class="pop-links"><button data-action="onlineTranslate">${translation?'在线核对翻译':'翻译所选文字'} ↗</button>${segment?`<button data-focus="${segment.id}">记到笔记</button>`:''}</div>${state.highlight==='manual'&&segment?`<button class="button soft wide" data-mark="${segment.id}" style="margin-top:9px">标记这一段重点</button>`:''}<small style="display:block;margin-top:9px">在线翻译仅发送选中文字至 MyMemory；不会发送整份录音或课件。</small>`;pop.hidden=false;pop.style.left=Math.max(10,Math.min(window.innerWidth-pop.offsetWidth-10,rect.left))+'px';pop.style.top=Math.max(10,Math.min(window.innerHeight-pop.offsetHeight-85,rect.bottom+9))+'px';}
document.addEventListener('mouseup',showSelectionTranslation);
document.addEventListener('touchend',()=>setTimeout(showSelectionTranslation,200));
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="onlineTranslate"]');if(!button||!selectedPhrase)return;const captured={...selectedPhrase},result=$('#selectionResult');if(!result)return;button.disabled=true;result.innerHTML='<p>正在翻译…</p>';try{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);let response;try{response=await fetch('https://api.mymemory.translated.net/get?'+new URLSearchParams({q:captured.text,langpair:'en|zh-CN'}),{signal:controller.signal})}finally{clearTimeout(timeout)}const data=await response.json();if(!response.ok||Number(data.responseStatus)!==200||!data.responseData?.translatedText)throw new Error('翻译服务暂不可用');if(selectedPhrase?.text!==captured.text||!result.isConnected)return;result.innerHTML=`<h3>${esc(data.responseData.translatedText)}</h3><small>MyMemory 在线翻译 · 专业术语请结合上下文核对</small>`;}catch{if(result.isConnected)result.innerHTML='<p>在线翻译暂不可用，可查看本段参考译文或稍后重试。</p>';}finally{button.disabled=false;}});

document.addEventListener('click',event=>{if(event.target.closest('.segment p,.uploaded-text')&&!event.target.closest('button'))showSelectionTranslation();});
document.addEventListener('keyup',event=>{if(event.key==='Shift'||event.key.startsWith('Arrow'))showSelectionTranslation();});
